async function fetchGrTaxes() {
  if (!window._rpt) { toast('Generate a report first.', 'err'); return; }
  const { bks } = window._rpt;
  const missing = bks.filter(b => b && b.id && !String(b.id).startsWith('_') && (b.taxPending || (b.ct === 0 && b.vat === 0 && b.at === 0)));
  if (!missing.length) { toast('All bookings already have tax data.'); return; }
  const btn = document.getElementById('fetch-gr-btn');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="ti ti-loader"></i> Fetching taxes…'; }
  toast('Fetching Greek taxes for ' + missing.length + ' bookings…', '');
  let updated = 0, note = '';
  try {
    const r = await fetch('/api/taxes/fetch', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ids: missing.map(b => String(b.id)) }) });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || ('HTTP ' + r.status));
    const eur = m => (m && m.cents != null ? m.cents / 100 : 0);
    Object.entries(d.results || {}).forEach(([id, t]) => {
      const idx = S.bks.findIndex(x => x && String(x.id) === id);
      if (idx < 0) return;
      const ct = eur(t.climate_tax), vat = eur(t.vat), at = eur(t.accommodation_tax);
      S.bks[idx].ct = ct; S.bks[idx].bvPrevat = eur(t.booking_value_pre_vat); S.bks[idx].vat = vat; S.bks[idx].at = at;
      S.bks[idx].nbv = eur(t.net_value) || ((+S.bks[idx].gross || 0) - ct - vat - at); S.bks[idx].trHost = ct + vat + at;
      delete S.bks[idx].taxPending;
      updated++;
    });
    if (d.skipped) note = ' (' + d.skipped + ')';
    else if (d.throttled) note = ' (Hosthub rate limit - the rest arrive in the background)';
    else if (d.missing && d.missing.length) note = ' (' + d.missing.length + ' not answered yet - retried in the background)';
  } catch (e) { toast('Tax fetch failed: ' + e.message, 'err'); }
  if (updated) save();
  if (btn) { btn.disabled = false; btn.innerHTML = updated ? '<i class="ti ti-check"></i> Taxes loaded' : '<i class="ti ti-refresh"></i> Fetch taxes'; }
  toast('Greek taxes loaded for ' + updated + ' of ' + missing.length + ' bookings' + note + '.', updated ? 'ok' : 'err');
  if (updated) renderRpt();
}
